properties.query:
let threshold = 10;
// Must stay <= queryPeriod. Wider than queryFrequency so a burst that straddles two runs
// still reaches the threshold.
let lookback = 1h;
// Must equal queryFrequency. A user is only evaluated when a secret event of theirs was
// ingested since the previous run, so the next run does not re-alert on a burst it has
// already counted - see 'Delinea - Failed authentication spike'.
let newSince = 30m;
let secretEventPattern = @"(?i)\.Secret\.(Viewed|Exported|Downloaded|Retrieved|Copied)";
let secretEvents =
    DelineaAuditEvents_CL
    | where TimeGenerated > ago(lookback)
    | extend IngestedAt = ingestion_time()
    | extend d = parse_json(RawData)
    | extend EventName = tostring(d.eventType.name), SrcIP = tostring(d.source.host.network.ipAddress)
    | where EventName matches regex secretEventPattern;
let recentUsers = secretEvents | where IngestedAt > ago(newSince) | distinct User;
secretEvents
| where User in (recentUsers)
| extend IsExport = EventName has_any ("Exported", "Downloaded", "Retrieved", "Copied")
| summarize DistinctSecrets = dcount(SecretId), Secrets = make_set(SecretId, 50),
            TotalOperations = count(), Exports = countif(IsExport), Secret = take_any(SecretId),
            StartTime = min(TimeGenerated), EndTime = max(TimeGenerated)
        by User, SrcIP
| where DistinctSecrets >= threshold
| sort by DistinctSecrets desc
